-- Cadastro idempotente: Conexão Equestre → projeto "Novo site Conexão Equestre" → vínculo Maisis.
-- Gerado por build-sql.mjs a partir de conexao-equestre.json. Não cria usuários Auth nem memberships.
begin;
select pg_advisory_xact_lock(hashtext('onboard:conexao-equestre'));
do $onboard$
declare cid uuid; pid uuid; aid uuid; tid uuid; payload jsonb := '{"roadmap":{"stack":{"architecture":{"title":"A tecnologia do novo site.","description":"Pacote Básico: site de página única, estático e rápido, com todo o conteúdo atual reorganizado. Os pacotes Completo e Plataforma adicionam painel de edição, agenda e inscrições sobre esta mesma base.","inputs":[{"id":"site","brand":"","title":"Site de página única","tool":"HTML, CSS e JavaScript","detail":"Seções âncora, menu dos quatro grupos e blocos expansíveis com o conteúdo integral","href":"https://developer.mozilla.org/pt-BR/docs/Web/HTML"},{"id":"whatsapp","brand":"","title":"Contato pelo WhatsApp","tool":"WhatsApp Business","detail":"Botão fixo e formulário que abre a conversa já preenchida","href":"https://business.whatsapp.com"},{"id":"midia","brand":"","title":"Mapa e vídeos","tool":"Google Maps + YouTube","detail":"Mapa da sede e canal da Conexão incorporados","href":"https://www.youtube.com"}],"core":{"id":"core","brand":"vercel","title":"Hospedagem em CDN","tool":"Vercel","detail":"Previsto para o site final · protótipo servido pelo painel da nó","href":"https://vercel.com"},"services":[{"id":"dominio","brand":"","title":"Domínio e HTTPS","tool":"conexaoequestre.com.br","detail":"Apontamento do domínio atual e redirecionamento das URLs antigas · após aprovação","href":"https://registro.br"},{"id":"seo","brand":"","title":"SEO básico","tool":"Meta tags + dados estruturados","detail":"Título, descrição, Open Graph e negócio local para o Google","href":"https://developers.google.com/search/docs"},{"id":"painel","brand":"supabase","title":"Painel de edição","tool":"Supabase","detail":"Somente nos pacotes Completo e Plataforma","href":"https://supabase.com"}],"caption":"O protótipo navegável é o Pacote Básico pronto para aprovação. Hospedagem, domínio e painel dependem do pacote escolhido e ainda não foram ativados."}},"costs":[],"next_steps":{"presentation":{"phase_mode":"source","review_label":"Proposta em análise","review_description":"A Maisis apresenta três pacotes para o novo site da Conexão Equestre. O protótipo navegável corresponde ao Pacote Básico, base dos três. Nenhum pacote foi aprovado ainda.","prototype_title":"Navegue pelo novo site.","editor_lock_reason":"O Editor fica bloqueado até a aprovação do pacote. Navegue pela aba Protótipo e envie suas observações à Maisis.","hero_title":"O novo site da Conexão Equestre, pronto para aprovação.","hero_description":"Explore o protótipo do site de página única, conheça a tecnologia e compare os três pacotes propostos.","infrastructure_title":"Três pacotes para o novo site.","scope_options":[{"label":"Básico · R$ 2 mil · Site de uma página","selected":false,"features":["Site de página única com todo o conteúdo atual reorganizado em seções: A Hípica, Para pessoas, Para cavalos, Estrutura, Equipe, Eventos, Equoterapia, Parceiros e Contato.","Identidade preservada: logo, verde e âmbar; fotos atuais tratadas.","WhatsApp fixo, Google Maps, YouTube, Instagram e Facebook; formulário via WhatsApp/e-mail.","SEO básico e redirecionamento das URLs antigas para as seções; hospedagem rápida em CDN com HTTPS.","Prazo estimado: 1–2 semanas. 1 rodada de ajustes. Suporte 15 dias."]},{"label":"Completo · R$ 5 mil · Site institucional com painel","selected":false,"features":["Tudo do Básico, com até 15 páginas internas espelhando o menu atual.","Painel de edição para a equipe da Conexão: textos, datas e valores de cursos, fotos, equipe e parceiros.","Agenda de cursos e eventos com página por evento e inscrição via WhatsApp ou link.","Formulário real com envio por e-mail, galeria de fotos e vídeos, SEO por página, sitemap, redirects 301, Analytics e Search Console.","Migração das imagens e desligamento assistido do WordPress. Prazo estimado: 3–5 semanas. 2 rodadas. Suporte 30 dias."]},{"label":"Plataforma · R$ 10 mil · Site + inscrições e relacionamento","selected":false,"features":["Tudo do Completo, com inscrições online em cursos, workshops e passeios: vagas, Pix e cartão, confirmação automática.","Agendamento de passeios e aulas experimentais com horários disponíveis.","Área do cliente: inscrições, certificados do Horsemanship e ficha do cavalo hospedado.","Blog e newsletter, versão em inglês dos cursos internacionais, site instalável no celular e feed do Instagram.","Relatórios de inscrições, contatos e receita por curso. Prazo estimado: 6–9 semanas. 3 rodadas. Suporte 60 dias."]}],"scope_note":"Nenhum pacote foi aprovado ainda. Valores definidos pela proposta de 20/10/2026; custos recorrentes de domínio, e-mail e gateway de pagamento serão confirmados por pacote antes do fechamento. Os prazos são estimativas da proposta, não datas de entrega.","hide_project_navigation":true},"task_details":{}},"references":["Site atual: https://conexaoequestre.com.br/ (20 páginas levantadas em 20/10/2026)","Proposta: app/onboarding/conexao-equestre/PROPOSTA-PACOTES.md","Protótipo: lp-basica-v1 (Pacote Básico)"],"tiers":{},"preferred_tier":null,"prototype_url":"/prototipos/conexao-equestre/lp-basica-v1/index.html"},"tasks":[{"source_id":"p0-1","title":"Levantamento do conteúdo do site atual (20 páginas)","phase":"Fase 0 · Proposta","status":"concluido","note":"Concluído em 20/10/2026 — textos, menu, equipe, contatos e imagens extraídos do WordPress atual.","week":1,"position":0},{"source_id":"p0-2","title":"Proposta com três pacotes (Básico, Completo, Plataforma)","phase":"Fase 0 · Proposta","status":"concluido","note":"Concluído em 20/10/2026 — PROPOSTA-PACOTES.md com escopo, prazos e suporte por pacote.","week":1,"position":1},{"source_id":"p0-3","title":"Protótipo navegável do Pacote Básico (site de uma página)","phase":"Fase 0 · Proposta","status":"concluido","note":"Concluído em 20/10/2026 — disponível na aba Protótipo, com todo o conteúdo atual.","week":1,"position":2},{"source_id":"p0-4","title":"Apresentação à Conexão Equestre pela Maisis","phase":"Fase 0 · Proposta","status":"a_fazer","note":"Depende da agenda da Maisis com o cliente.","week":2,"position":3},{"source_id":"p0-5","title":"Escolha do pacote e aprovação do protótipo","phase":"Fase 0 · Proposta","status":"a_fazer","note":"Define o escopo das próximas fases.","week":2,"position":4},{"source_id":"p1-1","title":"Ajustes de conteúdo e fotos após a aprovação","phase":"Fase 1 · Produção","status":"a_fazer","note":"Rodadas conforme o pacote escolhido.","week":3,"position":5},{"source_id":"p1-2","title":"Domínio, hospedagem e redirecionamento das URLs antigas","phase":"Fase 1 · Produção","status":"a_fazer","note":"Após aprovação; o WordPress atual permanece no ar até a virada.","week":3,"position":6},{"source_id":"p1-3","title":"Publicação e desligamento do site antigo","phase":"Fase 1 · Produção","status":"a_fazer","note":"Início do período de suporte do pacote.","week":4,"position":7}]}'::jsonb; task jsonb; details jsonb := '{}'::jsonb;
begin
  select id into aid from public.agencies where slug='maisis';
  if aid is null then raise exception 'Agency % not found', 'maisis'; end if;
  if not exists(select 1 from public.agencies where id=aid and name='Maisis Publicidade' and active) then raise exception 'Agency identity/status mismatch'; end if;
  select id into cid from public.clients where slug='conexao-equestre';
  if cid is null then
    if exists(select 1 from public.clients where name ilike '%conex%' or name ilike '%equestre%') then raise exception 'Review existing similar client'; end if;
    insert into public.clients(name,slug) values('Conexão Equestre','conexao-equestre') returning id into cid;
  elsif not exists(select 1 from public.clients where id=cid and name='Conexão Equestre') then raise exception 'Client identity mismatch'; end if;
  if (select count(*) from public.projects where client_id=cid and name='Novo site Conexão Equestre')>1 then raise exception 'Duplicate project'; end if;
  select id into pid from public.projects where client_id=cid and name='Novo site Conexão Equestre';
  if pid is null then
    insert into public.projects(client_id,name,niche,lead_status,project_status,modules)
    values(cid,'Novo site Conexão Equestre','centro hípico · Bragança Paulista','JANELA_DE_DECISAO','EM_REVISAO_CLIENTE','{"como_funciona":"ativo","prototipo":"ativo","etapas":"ativo","editor":"bloqueado","versoes":"bloqueado","marca":"bloqueado"}'::jsonb) returning id into pid;
  else
    update public.projects set niche='centro hípico · Bragança Paulista',project_status='EM_REVISAO_CLIENTE',modules=modules || '{"como_funciona":"ativo","prototipo":"ativo","etapas":"ativo","editor":"bloqueado","versoes":"bloqueado","marca":"bloqueado"}'::jsonb where id=pid;
  end if;
  if exists(select 1 from public.agency_projects where project_id=pid and agency_id<>aid) then raise exception 'Project already assigned to another agency'; end if;
  insert into public.agency_projects(agency_id,project_id) values(aid,pid) on conflict(project_id) do nothing;
  for task in select value from jsonb_array_elements(payload->'tasks') loop
    tid := null;
    select k.id into tid from public.kanban_items k where k.project_id=pid and k.title=task->>'title';
    if tid is null then
      insert into public.kanban_items(project_id,title,phase,status,position)
      values(pid,task->>'title',task->>'phase',(task->>'status')::public.kanban_status,(task->>'position')::integer) returning id into tid;
    else
      update public.kanban_items set phase=task->>'phase',status=(task->>'status')::public.kanban_status,position=(task->>'position')::integer where id=tid;
    end if;
    details := details || jsonb_build_object(tid::text,jsonb_build_object('source_id',task->>'source_id','note',task->>'note','week',task->'week'));
  end loop;
  insert into public.roadmaps(project_id,stack,costs,next_steps,"references",tiers,prototype_url,published_at)
  values(pid,payload->'roadmap'->'stack',payload->'roadmap'->'costs',(payload->'roadmap'->'next_steps') || jsonb_build_object('task_details',details),payload->'roadmap'->'references','{}',payload->'roadmap'->>'prototype_url',now())
  on conflict(project_id) do update set stack=excluded.stack,costs=excluded.costs,next_steps=excluded.next_steps,"references"=excluded."references",prototype_url=excluded.prototype_url,published_at=coalesce(roadmaps.published_at,excluded.published_at);
end $onboard$;
commit;
select c.id client_id,p.id project_id,a.id agency_id,c.name,p.lead_status,p.project_status,p.modules,r.prototype_url,
(select count(*) from public.kanban_items where project_id=p.id) tasks,
(select count(*) from public.kanban_items where project_id=p.id and status='concluido') completed,
(select count(*) from public.memberships where client_id=c.id) client_memberships
from public.clients c join public.projects p on p.client_id=c.id join public.agency_projects ap on ap.project_id=p.id join public.agencies a on a.id=ap.agency_id join public.roadmaps r on r.project_id=p.id where c.slug='conexao-equestre';
